import { Context, Effect, Schema, Scope } from 'effect'

export const RuntimeExecutionMode = Schema.Literals(['exec', 'workflow', 'job', 'test'])
export type RuntimeExecutionMode = typeof RuntimeExecutionMode.Type

export const RuntimeCapabilityKind = Schema.Literals([
  'tool',
  'orbit',
  'secret',
  'host',
  'state',
  'git',
  'artifact',
  'job',
  'workflow_step',
])
export type RuntimeCapabilityKind = typeof RuntimeCapabilityKind.Type

export const RuntimeMetadata = Schema.Record(Schema.String, Schema.Unknown)
export type RuntimeMetadata = typeof RuntimeMetadata.Type

export const RuntimeMountedInput = Schema.Struct({
  name: Schema.String,
  contentType: Schema.optional(Schema.String),
  data: Schema.String,
  sha256: Schema.optional(Schema.String),
})
export type RuntimeMountedInput = typeof RuntimeMountedInput.Type

export const RuntimeExecutionRequest = Schema.Struct({
  code: Schema.String,
  mode: RuntimeExecutionMode,
  timeoutMs: Schema.optional(Schema.Number),
  executionInputs: Schema.optional(Schema.Array(RuntimeMountedInput)),
  sourceFilter: Schema.optional(Schema.Array(Schema.String)),
  features: Schema.optional(RuntimeMetadata),
})
export type RuntimeExecutionRequest = typeof RuntimeExecutionRequest.Type

export const TrustedExecutionContext = Schema.Struct({
  scopeId: Schema.String,
  runId: Schema.String,
  attributionId: Schema.optional(Schema.String),
  machineId: Schema.optional(Schema.String),
  trace: Schema.optional(RuntimeMetadata),
  grants: Schema.optional(RuntimeMetadata),
})
export type TrustedExecutionContext = typeof TrustedExecutionContext.Type

export const RuntimeNamespaceRequirement = Schema.Struct({
  namespace: Schema.String,
  bindingKind: RuntimeCapabilityKind,
  optional: Schema.optional(Schema.Boolean),
})
export type RuntimeNamespaceRequirement = typeof RuntimeNamespaceRequirement.Type

export const RuntimeCapabilityUsage = Schema.Struct({
  kind: RuntimeCapabilityKind,
  key: Schema.String,
  metadata: Schema.optional(RuntimeMetadata),
})
export type RuntimeCapabilityUsage = typeof RuntimeCapabilityUsage.Type

export const RuntimePlan = Schema.Struct({
  requiredNamespaces: Schema.Array(RuntimeNamespaceRequirement),
  aliasMap: Schema.Record(Schema.String, Schema.String),
  capabilities: Schema.Array(RuntimeCapabilityUsage),
  mountedInputs: Schema.Array(RuntimeMountedInput),
  generatedTypeBlocks: Schema.Array(Schema.String),
  warnings: Schema.Array(Schema.String),
})
export type RuntimePlan = typeof RuntimePlan.Type

export interface RuntimePlanningResult {
  readonly runtimePlan: RuntimePlan
  readonly hostPlan?: unknown
}

export const RuntimeArtifactRef = Schema.Struct({
  id: Schema.String,
  kind: Schema.String,
  contentType: Schema.optional(Schema.String),
  url: Schema.optional(Schema.String),
  sizeBytes: Schema.optional(Schema.Number),
  metadata: Schema.optional(RuntimeMetadata),
})
export type RuntimeArtifactRef = typeof RuntimeArtifactRef.Type

export const RuntimeExecutionResult = Schema.Struct({
  mode: RuntimeExecutionMode,
  result: Schema.optional(Schema.Unknown),
  error: Schema.optional(Schema.String),
  logs: Schema.Array(Schema.String),
  warnings: Schema.Array(Schema.String),
  timings: Schema.Record(Schema.String, Schema.Number),
  metadata: Schema.optional(RuntimeMetadata),
})
export type RuntimeExecutionResult = typeof RuntimeExecutionResult.Type

export type RuntimeErrorReason =
  | 'validation'
  | 'planning'
  | 'provider'
  | 'host'
  | 'state'
  | 'artifact'
  | 'timeout'
  | 'internal'

export class RuntimeError extends Error {
  readonly _tag = 'RuntimeError'

  constructor(
    readonly reason: RuntimeErrorReason,
    message: string,
    readonly details?: unknown
  ) {
    super(message)
    this.name = 'RuntimeError'
  }
}

export function unwrapRuntimeErrorCause(error: unknown): unknown {
  if (!(error instanceof RuntimeError)) return error
  const details = error.details
  if (!details || typeof details !== 'object' || !('cause' in details)) return error
  return (details as { cause: unknown }).cause
}

