export type RuntimeHostDispatchTaggedInput =
  | {
      readonly kind: 'outbound_fetch'
      readonly outboundFetch: unknown
      readonly raw: unknown
    }
  | {
      readonly kind: 'secret'
      readonly secret: unknown
      readonly raw: unknown
    }
  | {
      readonly kind: 'sand'
      readonly sand: unknown
      readonly raw: unknown
    }
  | {
      readonly kind: 'namespace_tool'
      readonly namespace: string
      readonly tool: string
      readonly args: unknown
      readonly raw: unknown
    }
  | {
      readonly kind: 'legacy_key'
      readonly key: string
      readonly args: unknown
      readonly raw: unknown
    }
  | {
      readonly kind: 'unknown'
      readonly raw: unknown
    }

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value)

export const normalizeRuntimeHostDispatchInput = (
  input: unknown
): RuntimeHostDispatchTaggedInput => {
  if (!isRecord(input)) return { kind: 'unknown', raw: input }

  if ('outboundFetch' in input) {
    return { kind: 'outbound_fetch', outboundFetch: input.outboundFetch, raw: input }
  }

  if ('secret' in input) {
    return { kind: 'secret', secret: input.secret, raw: input }
  }

  if ('sand' in input) {
    return { kind: 'sand', sand: input.sand, raw: input }
  }

  if (typeof input.namespace === 'string' && typeof input.tool === 'string') {
    return {
      kind: 'namespace_tool',
      namespace: input.namespace,
      tool: input.tool,
      args: input.args,
      raw: input,
    }
  }

  if (typeof input.key === 'string') {
    return { kind: 'legacy_key', key: input.key, args: input.args, raw: input }
  }

  return { kind: 'unknown', raw: input }
}

