import { Context, Effect, Layer } from 'effect'
import { RuntimeError } from '@hrbr/runtime-core'

export interface RuntimeMcpInvocationInput {
  readonly namespace: string
  readonly toolName: string
  readonly invoke: () => Promise<unknown>
}

export interface RuntimeMcpInvocationResult {
  readonly raw: unknown
  readonly value: unknown
  readonly warnings: readonly string[]
  readonly isError: boolean
  readonly errorMessage?: string | undefined
}

export interface RuntimeMcpProvider {
  readonly invoke: (
    input: RuntimeMcpInvocationInput
  ) => Effect.Effect<RuntimeMcpInvocationResult, RuntimeError>
}

export const RuntimeMcpProvider = Context.Service<RuntimeMcpProvider>(
  '@hrbr/runtime-provider-mcp/RuntimeMcpProvider'
)

export const RuntimeMcpProviderLive = Layer.succeed(RuntimeMcpProvider, {
  invoke: (input) =>
    Effect.tryPromise({
      try: async () => finalizeRuntimeMcpResult(await input.invoke()),
      catch: (cause) =>
        new RuntimeError('provider', 'MCP provider invocation failed', {
          namespace: input.namespace,
          toolName: input.toolName,
          cause,
        }),
    }),
})

export function normalizeMcpResult(raw: unknown): unknown {
  if (!raw || typeof raw !== 'object') return raw
  const r = raw as Record<string, unknown>

  if (r.structuredContent !== undefined) return r.structuredContent

  const content = r.content as Array<{ type: string; text?: string }> | undefined
  if (!content || !Array.isArray(content) || content.length === 0) return raw

  const texts = content.filter((c) => c.type === 'text' && c.text).map((c) => c.text!)
  if (texts.length === 0) return raw

  const joined = texts.length === 1 ? texts[0]! : texts.join('\n')

  try {
    return JSON.parse(joined)
  } catch {
    return joined
  }
}

export function isMcpErrorResult(raw: unknown): boolean {
  return !!raw && typeof raw === 'object' && (raw as { isError?: unknown }).isError === true
}

const MCP_WARNING_MESSAGE_MAX = 800
const MCP_WARNING_MAX_ENTRIES = 10

export function extractMcpWarnings(result: unknown): string[] {
  if (!result || typeof result !== 'object') return []
  const r = result as Record<string, unknown>
  const content = r.content
  if (!Array.isArray(content) || content.length === 0) return []
  const out: string[] = []
  for (const block of content) {
    if (out.length >= MCP_WARNING_MAX_ENTRIES) break
    if (!block || typeof block !== 'object') continue
    const b = block as { type?: unknown; text?: unknown }
    if (b.type !== 'text') continue
    if (typeof b.text !== 'string') continue
    const trimmed = b.text.trim()
    if (!trimmed) continue
    const first = trimmed.charAt(0)
    if (first === '{' || first === '[') continue
    out.push(
      trimmed.length > MCP_WARNING_MESSAGE_MAX
        ? trimmed.slice(0, MCP_WARNING_MESSAGE_MAX) + '…[truncated]'
        : trimmed
    )
  }
  return out
}

export function mcpErrorResultMessage(result: unknown): string {
  const normalized = normalizeMcpResult(result)
  if (typeof normalized === 'string' && normalized.trim()) return normalized.slice(0, 1_000)
  try {
    return JSON.stringify(normalized).slice(0, 1_000)
  } catch {
    return 'MCP tool returned isError=true'
  }
}

export function finalizeRuntimeMcpResult(raw: unknown): RuntimeMcpInvocationResult {
  const isError = isMcpErrorResult(raw)
  return {
    raw,
    value: normalizeMcpResult(raw),
    warnings: extractMcpWarnings(raw),
    isError,
    ...(isError ? { errorMessage: mcpErrorResultMessage(raw) } : {}),
  }
}
